import{_ as e,a,o,a4 as n}from"./chunks/framework.-FZumj2l.js";const m=JSON.parse(`{"title":"Export Transactions","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-transactions-export","title":"Export Transactions (CSV)","description":"Download the transactions datagrid as a CSV file — the same data the admin Transactions \\"Export\\" button produces. Honours the same filters as the listing.","query":"curl -X GET \\"https://your-domain.com/api/admin/transactions/export?format=csv\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: text/csv\\" \\\\\\n  --output transactions.csv\\n","response":"# Binary response: a text/csv attachment is written to transactions.csv\\n# (Content-Disposition: attachment; filename=\\"transactions.csv\\"). Sample contents:\\n\\nID,\\"Transaction ID\\",\\"Invoice ID\\",\\"Order ID\\",Status,Date\\n6,605a2919e8a49b907e98f3cc8f71397d,585,41,paid,\\"2026-06-04 17:52:47\\"\\n"},{"id":"admin-transactions-export-xlsx","title":"Export Transactions (XLSX)","description":"Download the transactions datagrid as an XLSX file — the same data the admin Transactions \\"Export\\" button produces. Honours the same filters as the listing.","query":"curl -X GET \\"https://your-domain.com/api/admin/transactions/export?format=xlsx\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\\" \\\\\\n  --output transactions.xlsx\\n","response":"# Binary response: an XLSX workbook is written to disk\\n# (Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\\n#  Content-Disposition: attachment; filename=\\"transactions.xlsx\\").\\n# Same columns as the CSV export, as the first sheet's header row plus one row per record.\\n"},{"id":"admin-transactions-export-xls","title":"Export Transactions (XLS)","description":"Download the transactions datagrid as an XLS file — the same data the admin Transactions \\"Export\\" button produces. Honours the same filters as the listing.","query":"curl -X GET \\"https://your-domain.com/api/admin/transactions/export?format=xls\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/vnd.ms-excel\\" \\\\\\n  --output transactions.xls\\n","response":"# Binary response: an XLS workbook is written to disk\\n# (Content-Type: application/vnd.ms-excel\\n#  Content-Disposition: attachment; filename=\\"transactions.xls\\").\\n# Same columns as the CSV export, as the first sheet's header row plus one row per record.\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/sales/transactions/export.md","filePath":"api/rest-api/admin/sales/transactions/export.md","lastUpdated":1784902076000}`),s={name:"api/rest-api/admin/sales/transactions/export.md"};function r(i,t,d,c,p,l){return o(),a("div",null,t[0]||(t[0]=[n('<h1 id="export-transactions" tabindex="-1">Export Transactions <a class="header-anchor" href="#export-transactions" aria-label="Permalink to &quot;Export Transactions&quot;">​</a></h1><p>Downloads the transactions datagrid as a <strong>csv, xls or xlsx file</strong> — the same data the admin <strong>Sales → Transactions</strong> &quot;Export&quot; button produces. The response is a binary file attachment, not JSON. Requires the <code>sales.transactions.view</code> permission.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/transactions/export</code></td><td>GET</td></tr></tbody></table><h2 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h2><p>The export carries the six datagrid columns, in order:</p><table tabindex="0"><thead><tr><th>Header</th><th>Value</th></tr></thead><tbody><tr><td><code>ID</code></td><td>Transaction id.</td></tr><tr><td><code>Transaction ID</code></td><td>The payment gateway&#39;s transaction id.</td></tr><tr><td><code>Invoice ID</code></td><td>The related invoice&#39;s number.</td></tr><tr><td><code>Order ID</code></td><td>The parent order&#39;s number.</td></tr><tr><td><code>Status</code></td><td>The transaction status (e.g. <code>paid</code>, <code>pending</code>).</td></tr><tr><td><code>Date</code></td><td>When the transaction was recorded.</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query parameters&quot;">​</a></h2><p><code>format</code> selects the export format — <code>csv</code> (the default), <code>xls</code> or <code>xlsx</code>; any other value returns <code>422</code>. Send an <code>Accept</code> header matching the format: <code>text/csv</code>, <code>application/vnd.ms-excel</code> or <code>application/vnd.openxmlformats-officedocument.spreadsheetml.sheet</code>.</p><p>The export honours the <strong>same filters as the <a href="/api/rest-api/admin/sales/transactions/list.html">listing</a></strong>, so you export exactly the rows you&#39;re viewing: <code>id</code>, <code>transaction_id</code>, <code>invoice_id</code>, <code>order_id</code>, <code>status</code>, <code>created_at_from</code> / <code>_to</code>. (Pagination does not apply — the export returns every matching row.)</p><h2 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h2><p><code>sales.transactions.view</code></p>',12)]))}const u=e(s,[["render",r]]);export{m as __pageData,u as default};
